// Picks store: the member's picked book ids, kept in localStorage under the key "picks".

export function listPicks(): string[] {
  const picksJson = localStorage.getItem("picks");
  if (picksJson === null) {
    return [];
  }
  try {
    const picksArray = JSON.parse(picksJson);
    if (!Array.isArray(picksArray)) {
      return [];
    }
    return picksArray;
  } catch {
    return [];
  }
}

export function addPick(id: string): void {
    let picksArray = JSON.parse(localStorage.getItem("picks") || "[]");
    if (!Array.isArray(picksArray)) {
        picksArray = [];
    }
    if (picksArray.includes(id)) {
        return;
    }
    picksArray.push(id);
    localStorage.setItem("picks", JSON.stringify(picksArray));
}

export function removePick(id: string): void {
  let picks: string[] = JSON.parse(localStorage.getItem("picks") || "[]");
  picks = picks.filter(book => book !== id);
  localStorage.setItem("picks", JSON.stringify(picks));
}
